and returns a float prediction for the next day. Only the passed history is
used -- no globals, no access to any future data."""
import numpy as np


def naive(history) -> float:
    """Yesterday's value."""
    return float(np.asarray(history, dtype=float)[-1])


def seasonal_naive(history, season: int = 7) -> float:
    """Value from the same weekday one week ago (history[-season])."""
    h = np.asarray(history, dtype=float)
    return float(h[-season])


def moving_average_7(history, window: int = 7) -> float:
    """Mean of the last 7 observations."""
    return float(np.mean(np.asarray(history, dtype=float)[-window:]))


MODELS = {
    "naive": naive,
    "seasonal_naive": seasonal_naive,
    "moving_average_7": moving_average_7,
}
"})
