import numpy as np
import pytest

from backtest import backtest, evaluate_all, mae, mape, walk_forward
from forecasters import MODELS, moving_average_7, naive, seasonal_naive
from gen import generate_series

BIG = 1e9


# ---------------------------------------------------------------- fixtures

@pytest.fixture(scope="module")
def series():
    return generate_series()


@pytest.fixture(scope="module")
def results(series):
    return evaluate_all(series)


# ------------------------------------------------------- forecast contracts

def test_forecasters_return_scalar_float_from_history_only(series):
    for t in (60, 150, 364):
        hist = series[:t]
        for fc in MODELS.values():
            out = fc(hist)
            assert isinstance(out, float)


def test_walk_forward_split_boundaries(series):
    for t, pred, actual in walk_forward(series, naive):
        assert 60 <= t < len(series)
        assert actual == series[t]
    # first split must use history 0..59 to predict day 60
    _, pred60, actual60 = next(walk_forward(series, naive))
    assert pred60 == series[59] and actual60 == series[60]


# ------------------------------------------------------------- assertions

def test_seasonal_naive_beats_naive_on_mae(results):
    assert results["seasonal_naive"]["mae"] < results["naive"]["mae"]


def test_seasonal_naive_mae_under_7(results):
    assert results["seasonal_naive"]["mae"] < 7.0


def test_all_models_produce_finite_metrics(results):
    for name, m in results.items():
        assert np.isfinite(m["mae"]) and np.isfinite(m["mape"]), name


# ----------------------------------------------- no-lookahead proof

def test_no_lookahead_predictions_unchanged_when_future_poisoned(series):
    """Monkeypatch every value AFTER day t to 1e9; predictions for day t
    must be bit-identical. Proves models/backtest never read beyond t."""
    ts = [60, 61, 100, 200, 363]
    for t in ts:
        poisoned = series.copy()
        poisoned[t + 1:] = BIG          # all values after t are garbage
        for name, fc in MODELS.items():
            clean = float(fc(series[:t]))
            dirty = float(backtest(poisoned, fc)["preds_at_t"][t]) \
                if False else None
            # direct check through the same slicing backtest uses
            for _, p_clean, _ in walk_forward(series[: t + 1], fc):
                if _ == t:
                    break
            p_dirty = next(
                (p for tt, p, _ in walk_forward(poisoned[: t + 1], fc)
                 if tt == t), None
            )
            assert p_dirty == pytest.approx(clean, rel=0, abs=0), (name, t)


def test_no_lookahead_full_backtest_metrics_unchanged(series):
    """If we poison only days AFTER the evaluation horizon start-1... not
    applicable; instead verify poisoning future of each target leaves that
    target's prediction identical across full walk-forward run at t=200."""
    t = 200
    poisoned = series.copy()
    poisoned[t + 1:] = BIG
    for name, fc in MODELS.items():
        preds_clean = {tt: p for tt, p, _ in walk_forward(series, fc)}
        preds_dirty = {tt: p for tt, p, _ in walk_forward(poisoned, fc)}
        # predictions up to and including t are unaffected by future poison
        for tt in range(60, t + 1):
            assert preds_dirty[tt] == pytest.approx(preds_clean[tt],
                                                    rel=0, abs=0), (name, tt)


# ------------------------------------------------ MAPE zero-denominator policy

def test_mape_with_zero_actuals_no_zero_division():
    """Policy: days whose ACTUAL is 0 are excluded from MAPE entirely.
    A zero in actuals or preds must never raise ZeroDivisionError."""
    actuals = np.array([10.0, 0.0, 20.0, 0.0])
    preds = np.array([8.0, 5.0, 25.0, 0.0])
    got = mape(preds, actuals)  # must not raise
    expected = np.mean(np.abs(np.array([-0.2, 0.25])))
    assert got == pytest.approx(expected)
    # zero prediction is fine too (denominator is |actual|)
    assert np.isfinite(mape(np.zeros(4), actuals))


def test_mape_all_zero_actuals_returns_zero_not_crash():
    assert mape(np.array([1.0, 2.0]), np.array([0.0, 0.0])) == 0.0


def test_backtest_end_to_end_with_zero_in_series():
    s = generate_series()
    s = s.astype(float).copy()
    s[100] = 0.0
    s[250] = 0.0
    for name, fc in MODELS.items():
        m = backtest(s, fc)  # must not raise ZeroDivisionError
        assert np.isfinite(m["mae"]) and np.isfinite(m["mape"])
